import AppKit

/// Settings' Assistant pane (road map 12 A2): the person's Anthropic key
/// (spec §11 AI-8), the model (AI-11) and the chat settings (AI-20), above
/// the Transcription pane in `SettingsWindowController`'s one stack. Its
/// heading carries a `SettingsInfoButton` holding `explanation()` (SH-5).
///
/// **It mirrors the Transcription pane's key handling, rule for rule.** The
/// key is typed into a secure field and never shown back: a stored key is a
/// FIXED-LENGTH mask in the field's placeholder
/// (`SettingsWindowController.maskedPlaceholder`), never its `stringValue`;
/// Save writes what was typed and empties the field; "No API key is set." is
/// a state in the muted colour, not an error. There is no Verify and no
/// account link (AI-1: the app never calls Anthropic itself).
///
/// **A change ends each window's conversation.** A session keeps the key and
/// model it was opened with, so Save, Remove and a model that actually
/// changes post `AssistantConfiguration.didChangeNotification` — this pane is
/// its only poster — and each editor ends its session
/// (`EditorViewController.assistantConfigurationDidChange`). A model commit
/// that leaves `AssistantConfiguration.model` where it was posts nothing.
///
/// **A chat-settings change ends nothing** (AI-20). The compaction switch, its
/// threshold and the clearing switch apply at once, with no Save, and post
/// "settings" only when `AssistantChatSettings` actually changes; each
/// editor writes them to its open session. A threshold outside the range
/// beeps and the field shows the stored value again.
///
/// The store is a FACTORY, as the Transcription pane's is, so the harness and
/// the probes hand it a `MemoryStore` and no file is read or written.
///
/// **The month's spend (road map 13 P4, spec §11 P-7)** is the two labels
/// under the buttons: the UTC month folded from the spend folder's ledger
/// (`AssistantSpendMonth`) and the note that it is Frame Job's own estimate
/// (P-4). The folder is a FACTORY too, so the harness hands it an absent one.
/// `init` and `sync()` never read the ledger; `refreshSpend` does, when the
/// window shows and after each line `AssistantSpend.record` writes while it
/// is visible. Only the latest refresh's answer is shown.
final class AssistantSettingsPane: NSStackView, NSTextFieldDelegate {
    static let paneTitle = "Assistant"
    static let emptyPlaceholder = "Paste your key"
    /// The key row's label, which names the service the field does not.
    static let keyLabel = "Anthropic API key:"
    /// The Settings window's width less its two insets.
    private static let textWidth: CGFloat = 420

    private let store: () -> any SecretStore
    private let defaults: UserDefaults
    private let environment: [String: String]
    private let spendFolder: () -> URL?
    /// The reading `spendLabel` last showed, and the refresh whose answer may
    /// still be shown.
    private var shown: AssistantSpendMonth.Reading = .reading
    private var spendGeneration = 0

    let headingLabel = NSTextField(labelWithString: AssistantSettingsPane.paneTitle)
    let keyField = NSSecureTextField()
    let modelField = NSTextField()
    let compactBox = NSButton(checkboxWithTitle: "Compact when context reaches", target: nil, action: nil)
    let compactTokensField = NSTextField()
    let tokensLabel = NSTextField(labelWithString: "tokens")
    let clearToolResultsBox = NSButton(
        checkboxWithTitle:
            "Clear old tool results past \(AssistantChatSettings.clearTriggerTokens.formatted()) tokens",
        target: nil, action: nil)
    let statusLabel = NSTextField(wrappingLabelWithString: "")
    /// The heading's ⓘ, holding `explanation()` (SH-5).
    let infoButton = SettingsInfoButton(
        section: AssistantSettingsPane.paneTitle, infoText: AssistantSettingsPane.explanation())
    let spendLabel = NSTextField(wrappingLabelWithString: "")
    let spendNoteLabel = NSTextField(wrappingLabelWithString: AssistantSpendMonth.note)
    private(set) var saveButton: NSButton!
    private(set) var removeButton: NSButton!

    init(
        store: @escaping () -> any SecretStore, defaults: UserDefaults,
        environment: [String: String],
        spendFolder: @escaping () -> URL? = { AssistantSpend.folder() }
    ) {
        self.store = store
        self.defaults = defaults
        self.environment = environment
        self.spendFolder = spendFolder
        super.init(frame: .zero)
        build()
        sync()
        NotificationCenter.default.addObserver(
            self, selector: #selector(spendRecorded(_:)),
            name: AssistantSpend.didRecordNotification, object: nil)
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("AssistantSettingsPane does not support NSCoder")
    }

    private func build() {
        headingLabel.font = DS.sans(15, weight: .bold)
        headingLabel.textColor = DS.textStrong

        DSField.style(keyField)
        keyField.placeholderString = Self.emptyPlaceholder
        keyField.target = self
        keyField.action = #selector(saveClicked(_:))
        keyField.delegate = self
        keyField.widthAnchor.constraint(equalToConstant: 240).isActive = true

        DSField.style(modelField)
        modelField.placeholderString = AssistantConfiguration.defaultModel
        modelField.target = self
        modelField.action = #selector(modelChanged(_:))
        modelField.cell?.sendsActionOnEndEditing = true
        modelField.widthAnchor.constraint(equalToConstant: 240).isActive = true

        compactBox.font = DS.sans(13)
        compactBox.target = self
        compactBox.action = #selector(compactToggled(_:))
        compactBox.setAccessibilityIdentifier("settings.assistant.compact")
        DSField.style(compactTokensField)
        compactTokensField.alignment = .right
        compactTokensField.target = self
        compactTokensField.action = #selector(compactTokensChanged(_:))
        compactTokensField.cell?.sendsActionOnEndEditing = true
        compactTokensField.widthAnchor.constraint(equalToConstant: 84).isActive = true
        compactTokensField.setAccessibilityIdentifier("settings.assistant.compacttokens")
        tokensLabel.font = DS.sans(13)
        tokensLabel.textColor = DS.textMuted
        clearToolResultsBox.font = DS.sans(13)
        clearToolResultsBox.target = self
        clearToolResultsBox.action = #selector(clearToolResultsToggled(_:))
        clearToolResultsBox.setAccessibilityIdentifier("settings.assistant.cleartoolresults")

        statusLabel.font = DS.sans(12)
        statusLabel.textColor = DS.textMuted
        statusLabel.preferredMaxLayoutWidth = Self.textWidth
        infoButton.setAccessibilityIdentifier("settings.assistant.info")

        saveButton = StickerButton(
            title: "Save", style: .primary, target: self, action: #selector(saveClicked(_:)))
        removeButton = StickerButton(
            title: "Remove", style: .secondary, target: self, action: #selector(removeClicked(_:)))

        spendLabel.font = DS.sans(12)
        spendLabel.textColor = DS.textStrong
        spendLabel.preferredMaxLayoutWidth = Self.textWidth
        spendLabel.setAccessibilityIdentifier("settings.assistant.spend")
        spendNoteLabel.font = DS.sans(11)
        spendNoteLabel.textColor = DS.textFaint
        spendNoteLabel.preferredMaxLayoutWidth = Self.textWidth
        spendNoteLabel.setAccessibilityIdentifier("settings.assistant.spendnote")

        orientation = .vertical
        alignment = .leading
        spacing = 12
        let buttons = row([saveButton, removeButton])
        let compactRow = row([compactBox, compactTokensField, tokensLabel])
        compactRow.spacing = 6
        let views: [NSView] = [
            settingsSectionHeader(headingLabel, info: infoButton),
            row([fieldLabel(Self.keyLabel), keyField]),
            row([fieldLabel("Model:"), modelField]), compactRow, clearToolResultsBox,
            statusLabel, buttons, spendLabel, spendNoteLabel,
        ]
        for view in views { addArrangedSubview(view) }
        setCustomSpacing(16, after: buttons)
        setCustomSpacing(4, after: spendLabel)
    }

    private func row(_ views: [NSView]) -> NSStackView {
        let stack = NSStackView(views: views)
        stack.orientation = .horizontal
        stack.alignment = .centerY
        stack.spacing = 8
        // Hugs at its content, so its width is not a tie with the column's (#143).
        stack.setHuggingPriority(.required, for: .horizontal)
        return stack
    }

    // MARK: - Syncing

    /// The placeholder, the model, the chat settings, and whether Remove can
    /// do anything. Never writes `keyField.stringValue` (the Transcription
    /// pane's rule).
    func sync() {
        let stored = store().read()
        keyField.placeholderString =
            stored != nil ? SettingsWindowController.maskedPlaceholder : Self.emptyPlaceholder
        removeButton?.isEnabled = stored != nil
        modelField.stringValue = defaults.string(forKey: AssistantConfiguration.modelKey) ?? ""
        syncChatSettings()
        sayKeyState(stored: stored)
    }

    /// The stored chat settings; the threshold field is enabled only while
    /// compaction is on, and never written while it is being edited.
    private func syncChatSettings() {
        let settings = AssistantChatSettings.load(from: defaults)
        compactBox.state = settings.autoCompact ? .on : .off
        clearToolResultsBox.state = settings.clearToolResults ? .on : .off
        compactTokensField.isEnabled = settings.autoCompact
        if compactTokensField.currentEditor() == nil {
            compactTokensField.stringValue = settings.autoCompactTokens.formatted()
        }
    }

    func controlTextDidChange(_ notification: Notification) {
        guard notification.object as? NSTextField === keyField else { return }
        sayKeyState(stored: store().read())
    }

    /// "No API key is set." when neither the field, the store nor the
    /// environment has one; nothing otherwise.
    private func sayKeyState(stored: String?) {
        let typed = keyField.stringValue.trimmingCharacters(in: .whitespacesAndNewlines)
        let hasKey =
            !typed.isEmpty
            || AssistantConfiguration.credential(
                store: MemoryStore(stored), environment: environment) != nil
        say(hasKey ? "" : "No API key is set.", problem: false)
    }

    private func say(_ text: String, problem: Bool) {
        statusLabel.stringValue = text
        statusLabel.textColor = problem ? DS.textStrong : DS.textMuted
    }

    // MARK: - The month's spend

    /// The UTC month holding `now`, from the spend folder's ledger: no
    /// folder says so at once, an absent ledger is an empty month at once,
    /// and a present one reads "Reading…" while `AssistantSpendMonth.read`
    /// folds it — except that with `keepShown` a sentence already shown for
    /// a summary or a failure stays until the fold answers (P-7). Each call
    /// supersedes every earlier one.
    func refreshSpend(now: Date = Date(), keepShown: Bool = false) {
        spendGeneration += 1
        let generation = spendGeneration
        let month = AssistantSpendMonth.month(containing: now)
        guard let folder = spendFolder() else {
            showSpend(.noLedger, month: month)
            return
        }
        let ledger = folder.appendingPathComponent(AssistantSpend.ledgerName)
        guard FileManager.default.fileExists(atPath: ledger.path) else {
            showSpend(.summary(AssistantSpendMonth.Summary()), month: month)
            return
        }
        var keeps = false
        switch shown {
        case .summary, .failed: keeps = keepShown
        case .noLedger, .reading: keeps = false
        }
        if !keeps { showSpend(.reading, month: month) }
        AssistantSpendMonth.read(ledger: ledger, month: month) { [weak self] reading in
            guard let self, self.spendGeneration == generation else { return }
            self.showSpend(reading, month: month)
        }
    }

    private func showSpend(_ reading: AssistantSpendMonth.Reading, month: DateInterval) {
        shown = reading
        spendLabel.stringValue = AssistantSpendMonth.sentence(reading, month: month)
    }

    /// A ledger line was written: re-read it, only while the window shows.
    @objc private func spendRecorded(_ notification: Notification) {
        guard window?.isVisible == true else { return }
        refreshSpend(keepShown: true)
    }

    // MARK: - Buttons

    /// Writes what is in the field and then empties it.
    @objc func saveClicked(_ sender: Any?) {
        let typed = keyField.stringValue.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !typed.isEmpty else {
            NSSound.beep()
            return
        }
        do {
            try store().write(typed)
        } catch {
            keyField.stringValue = ""
            sync()
            say(error.localizedDescription, problem: true)
            return
        }
        keyField.stringValue = ""
        sync()
        say("Key saved.", problem: false)
        post("key")
    }

    @objc func removeClicked(_ sender: Any?) {
        do {
            try store().remove()
        } catch {
            sync()
            say(error.localizedDescription, problem: true)
            return
        }
        keyField.stringValue = ""
        sync()
        say("Key removed.", problem: false)
        post("key")
    }

    /// The model field's commit (Return or leaving it). Blank is AI-11's
    /// default.
    @objc func modelChanged(_ sender: Any?) {
        let before = AssistantConfiguration.model(defaults: defaults)
        let typed = modelField.stringValue.trimmingCharacters(in: .whitespacesAndNewlines)
        defaults.set(typed, forKey: AssistantConfiguration.modelKey)
        guard AssistantConfiguration.model(defaults: defaults) != before else { return }
        post("model")
    }

    // MARK: - Chat settings (AI-20)

    @objc func compactToggled(_ sender: Any?) {
        var settings = AssistantChatSettings.load(from: defaults)
        settings.autoCompact = compactBox.state == .on
        commit(settings)
    }

    @objc func clearToolResultsToggled(_ sender: Any?) {
        var settings = AssistantChatSettings.load(from: defaults)
        settings.clearToolResults = clearToolResultsBox.state == .on
        commit(settings)
    }

    /// The threshold field's commit (Return or leaving it). Outside the range
    /// beeps and shows the stored value again, writing nothing.
    @objc func compactTokensChanged(_ sender: Any?) {
        var settings = AssistantChatSettings.load(from: defaults)
        guard let tokens = Int(compactTokensField.stringValue.filter(\.isNumber)),
            AssistantChatSettings.compactTokensRange.contains(tokens)
        else {
            NSSound.beep()
            compactTokensField.stringValue = settings.autoCompactTokens.formatted()
            return
        }
        settings.autoCompactTokens = tokens
        commit(settings)
        compactTokensField.stringValue = tokens.formatted()
    }

    /// Saves and posts "settings" only when `settings` differs from what is
    /// stored; the controls show the stored settings after.
    private func commit(_ settings: AssistantChatSettings) {
        let changed = settings != AssistantChatSettings.load(from: defaults)
        if changed { settings.save(to: defaults) }
        syncChatSettings()
        if changed { post("settings") }
    }

    private func post(_ change: String) {
        NotificationCenter.default.post(
            name: AssistantConfiguration.didChangeNotification, object: self,
            userInfo: [AssistantConfiguration.changeKey: change])
    }

    /// The ⓘ's text in three paragraphs: what the assistant sends and to
    /// whom, what it costs and where the key is kept; the model; and what the
    /// chat settings do.
    static func explanation() -> String {
        let range = AssistantChatSettings.compactTokensRange
        return [
            "The assistant sends your messages, the project's details and the frames it renders "
                + "to Anthropic, using your own API key; what it costs is billed to that key. It "
                + "asks before writing a file. The key is kept in a file only you can read and "
                + "is never shown again once it is saved.",
            "Leave the model blank for \(AssistantConfiguration.defaultModel). Changing the key "
                + "or the model starts a new conversation.",
            "At the end of a turn past the compaction threshold "
                + "(\(range.lowerBound.formatted()) to \(range.upperBound.formatted()) tokens; "
                + "\(AssistantChatSettings.defaultCompactTokens.formatted()) by default), the "
                + "conversation is replaced by a summary, and earlier renders don't survive it. "
                + "Clearing lets Anthropic drop old tool results from what the model sees, even "
                + "mid-turn (never tool search results), and each clearing costs a fresh "
                + "prompt-cache write. Changing either setting keeps the conversation.",
        ].joined(separator: "\n\n")
    }
}


    /// The store's file, beside AssemblyAI's `assemblyai-key`.
    static let keyFileName = "anthropic-key"

    /// The environment override, read only when the store has nothing
    /// (R6-5, R6-9 (d)).
    static let environmentKey = "ANTHROPIC_API_KEY"

    /// The helper's `api_base` (AI-13): the stand-in server's address in a
    /// proof. `protocol.ts` calls it "an environment variable of its own".
    static let baseURLVariable = "RC_ASSISTANT_BASE_URL"

    /// The persisted model, Settings' Assistant pane from A2.
    static let modelKey = "FrameJobAssistantModel"

    /// AI-11's default.
    static let defaultModel = "claude-opus-5-5"

    /// The helper's `ChatSettings` (`agent/src/protocol.ts`): the person's
    /// chat settings from Settings' Assistant pane (AI-20). A dev build's
    /// `-RCDevAssistantAutoCompact <tokens>` replaces the threshold, even
    /// with compaction off, for a proof (AI-18).
    static func settingsJSON(defaults: UserDefaults = .standard) -> [String: Any] {
        var json = AssistantChatSettings.load(from: defaults).helperJSON
        #if FRAMEJOB_DEV_TOOLS
        if let tokens = devAutoCompactTokens(defaults: defaults) {
            json["auto_compact_tokens"] = tokens
        }
        #endif
        return json
    }

    /// Why the base-URL override cannot be used, in the sentence the session
    /// refuses with.
    enum ConfigurationError: LocalizedError, Equatable {
        case malformedBase(String)
        case insecureBase(String)

        var errorDescription: String? {
            switch self {
            case .malformedBase(let text):
                return "RC_ASSISTANT_BASE_URL “\(text)” is not a URL the assistant can reach."
            case .insecureBase(let host):
                return "A plain HTTP RC_ASSISTANT_BASE_URL is only allowed for a local server, "
                    + "and “\(host)” is not one."
            }
    /// The endpoint override, the `-RCRecordingFolder` idiom
    /// (`RecordingSetup.swift`). A whole base URL rather than a host, because
    /// the scheme is part of what is being overridden: the stand-in speaks
    /// plain HTTP.
    static let endpointArgument = "RCAssemblyAIEndpoint"

    /// The store-folder override (R6-9). A PATH, never a key — `ps` shows
    /// every launch argument to every user on the machine, which is the same
    /// reason R6-5 keeps the credential out of `transcribe`'s arguments.
    static let secretFolderArgument = "RCSecretFolder"

    /// The persisted region, the Settings window's popup.
    static let regionKey = "FrameJobAssemblyAIRegion"

    /// The environment override, read only when the store has nothing
    /// (R6-5, R6-9 (d)).
    static let environmentKey = "RC_ASSEMBLYAI_KEY"

    /// AssemblyAI's two data regions (road map 6 §2). A transcript made in
    /// one is not visible in the other, which is why this is a setting and
    /// not a fallback.
    enum Region: String, CaseIterable {
        case us
        case eu

        var base: URL {
            switch self {
            case .us: return Region.url("https://api.assemblyai.com")
            case .eu: return Region.url("https://api.eu.assemblyai.com")
            }
        }

        /// `URL(string:)` is optional because its input is usually somebody
        /// else's; these two are literals on the lines above. A parse that
        /// failed would be a typo there, and the fallback reaches no host at
        /// all — every request against it refuses, which is the safe
        /// direction: never a DIFFERENT server.
        private static func url(_ text: String) -> URL {
            URL(string: text) ?? URL(fileURLWithPath: "/dev/null")
        }

        var displayName: String {
            switch self {
            case .us: return "United States"
            case .eu: return "European Union"
            }
import AppKit

/// The two keys a feature may need (spec §11 CJ-3): the person's Anthropic
/// key (AI-8, Settings ▸ Assistant) and their AssemblyAI key (R6-5,
/// Settings ▸ Transcription).
enum ModelKey: String, CaseIterable {
    case anthropic, assemblyAI

    var displayName: String {
        switch self {
        case .anthropic: return "Anthropic"
        case .assemblyAI: return "AssemblyAI"
        }
    }

    /// The Settings pane that holds the key.
    var settingsSection: String {
        switch self {
        case .anthropic: return "Assistant"
        case .assemblyAI: return "Transcription"
        }
    }

    /// What a keyed menu item's title gains while it is off for this key
    /// (CJ-10, the owner's answer 4).
    var titleSuffix: String { " (needs your \(displayName) key)" }

    /// The clause every keyed tool's catalog description ends with (CJ-11),
    /// which the parity check's sixth part looks for (CJ-13).
    var catalogClause: String {
        "Keyed (spec §11 CJ-3): where it would send to \(displayName) it needs the person's "
            + "\(displayName) API key, and without one it refuses there with "
            + "\"\(ModelKeys.sentence(self))\""
    }
}

/// One row of the keyed table (CJ-12): a feature that sends to a model, its
/// key, the menu action that starts it (nil when it has none), the tools that
/// send for it, and whether it is keyed only when it would send.
struct KeyedFeature {
    let name: String
    let key: ModelKey
    let menuAction: Selector?
    let tools: [String]
    let conditional: Bool
}

/// The one test of whether a key is present, and everything a keyed surface
/// says when it is not (spec §11 CJ-10…CJ-13).
///
/// **Nothing is memoised.** A presence test is one small file read; a memo
/// would be wrong for a sheet's injected store and stale when another Frame
/// Job writes the key. The senders still read the credential to send it —
/// this answers only whether one resolves.
///
/// **`enabled` is always the caller's whole rule.** Neither `mark` overrides
/// it: `missing` says only WHY a control is off, so each caller's own key
/// term stays the gate its mutants test.
///
/// **A key saved or removed reaches every open keyed surface at once.** The
/// two keys post two different notifications, so one observer of each,
/// installed once, resets the main menu's satisfied marks and re-posts
/// `didChangeNotification`, the one a keyed surface observes. A menu item is
/// otherwise re-titled only by its validator, which does not run while a
/// sheet is up or with no editor in the responder chain.
enum ModelKeys {
    static let didChangeNotification = Notification.Name("FrameJobModelKeysDidChange")
    /// The notification's `userInfo` key; its value is the source key's
    /// `rawValue`.
    static let keyInfoKey = "key"
import AppKit

/// Settings ▸ Playback ▸ Background render (spec §11 G-38 (a)): a person's
/// setting, like AI-11's model and R6-12's key — no tool reads or writes it
/// and it has no MCP mirror. `PlaybackSettingsPane` is its one writer; a
/// proof sets it in the argument domain and writes nothing.
struct BackgroundRenderSettings: Equatable {
    /// Bool; absent = true.
    static let enabledKey = "FrameJobBackgroundRender"
    /// Int seconds; absent = the default, outside the range clamped into it.
    static let delayKey = "FrameJobBackgroundRenderDelay"
    static let defaultDelay = 5
    static let delayRange = 1...60

    var enabled = true
    var delaySeconds = BackgroundRenderSettings.defaultDelay

    static func load(from defaults: UserDefaults = .standard) -> BackgroundRenderSettings {
        var settings = BackgroundRenderSettings()
        if defaults.object(forKey: enabledKey) != nil {
            settings.enabled = defaults.bool(forKey: enabledKey)
        }
        if defaults.object(forKey: delayKey) != nil {
            let seconds = defaults.integer(forKey: delayKey)
            settings.delaySeconds = min(max(seconds, delayRange.lowerBound), delayRange.upperBound)
        }
        return settings
    }

    /// Writes both keys.
    func save(to defaults: UserDefaults = .standard) {
        defaults.set(enabled, forKey: Self.enabledKey)
        defaults.set(delaySeconds, forKey: Self.delayKey)
    }
}

/// What the idle clock's door answered (`Playback.startBackgroundRender`).
enum BackgroundStart {
    case started
    case notNeeded
    /// Seeking, restoring, rebuilding, holding, or the start refused (a
    /// window plays): the clock runs again.
    case busy
}

/// The idle clock (spec §11 G-38 (b), (c)). Main only.
///
/// **Activity** restarts it and stops the running background pass at once:
/// every event in `activityEvents` the app receives (a local monitor, so
/// pointer motion alone and events in other apps do not count), every
/// `.projectDocumentDidChange` of any document (live ticks included), and
/// every `syncPrefetch` of any transport — play, pause, a rate change, a
/// seek — which also makes that transport `current`. An agent's call counts
/// only when it edits or moves a transport.
///
/// **At the delay** (read from the stored setting at every restart), with
/// the setting on and no transport playing, `current` is asked to start a
/// pass; a playing transport or `.busy` runs the clock again, `.notNeeded`
/// waits for the next activity. `current` is weak,
/// and an invalidated `Playback` has no item, so a late fire finds nothing.
    /// state the sheet names, not an error (road map 6 §5d).
    func read() -> String?
    /// Replaces whatever is there. Throws when it cannot be written, because
    /// a Save button that said nothing and saved nothing is the failure this
    /// is for.
    func write(_ secret: String) throws
    /// Leaves nothing behind. Removing what is not there succeeds.
    func remove() throws
}

/// Why a store could not be written, in a sentence the Settings window can
/// show unchanged.
enum SecretStoreError: LocalizedError, Equatable {
    case unwritable(String)

    var errorDescription: String? {
        switch self {
        case .unwritable(let reason):
            return "The API key could not be saved: \(reason)"
        }
    }
}

/// The shipping conformer: one file, mode `0600`, in a directory created at
/// `0700`.
///
/// **The permissions are on the file from the moment it exists.** It is
/// created with `O_CREAT|O_EXCL` at mode `0600` under a temporary name and
/// `rename(2)`d into place — never written first and `chmod`ed after, which
/// would leave a window in which the key was world-readable, and never
/// through `Data.write`, whose `POSIXPermissions` would be applied to a file
/// that already existed. The rename is also what makes a replacement atomic:
/// a reader sees the old key or the new one, never a half-written file.
///
/// An EXISTING directory's mode is left alone. A person who tightened
/// `~/Library/Application Support/Frame Job/` themselves should keep what they
/// chose, and a directory the app did not create is not the app's to relax.
final class FileStore: SecretStore {

    /// The one spelling of AssemblyAI's file's name, and `name`'s default.
    static let fileName = "assemblyai-key"

/// The three containers are the seams: a later stage puts
/// `PreviewCanvasView` in `canvasContainer`, `InspectorViewController`'s view
/// in `inspectorContainer` and `TimelineView` in `timelineContainer`, and
/// replaces the placeholders that stand in for them now.
final class EditorViewController: NSViewController {
    // MARK: - Metrics (spec §3's table)

    static let toolbarHeight = DS.toolbarHeight
    /// The redesign's inspector width (`DS.panelWidth`, 304). The two clamps
